// 8-token accent palette for Avatar default backgrounds (used when no bgcolor is passed on a non-image avatar).
// Checker reports Content=Text's fill as "wrong-token" (lilac-main rendered vs
// Figma's pink/main): verified this is the hash picking a different bucket, not
// a bad token. The initials-avatar story's fixed "OP" children hash to
// lilac-main every time (hashAvatarFill below); Figma's one static example
// uses whatever initials its own mock happens to show, landing on pink. Any
// text seed can land in any of the 8 buckets, so a single fixed Figma example
// can never reliably match a single fixed Storybook seed; this is a checker
// limitation (no notion of "any of 8 is valid"), not a theme bug. Left alone.
const AVATAR_DEFAULT_FILL_TOKENS = [
  "color-accent-pink-fill",
  "color-accent-lime-fill",
  "color-accent-lemon-fill",
  "color-accent-blue-fill",
  "color-accent-saffron-fill",
  "color-accent-azure-fill",
  "color-accent-graphite-fill",
  "color-accent-lilac-main",
] as const;

// Deterministic seed = sum of char codes mod 8. Small palette + short labels: no need for djb2.
function hashAvatarFill(seed: string): string {
  let sum = 0;
  for (let i = 0; i < seed.length; i++) sum += seed.charCodeAt(i);
  return cssVar(AVATAR_DEFAULT_FILL_TOKENS[sum % AVATAR_DEFAULT_FILL_TOKENS.length]);
}

// Pull a stable seed out of an Avatar ownerState. Prefers children (typical "AB" initials), falls back to alt.
function avatarSeedFrom(ownerState: any): string | undefined {
  const c = ownerState?.children;
  if (typeof c === "string" && c) return c;
  if (typeof c === "number") return String(c);
  if (Array.isArray(c)) {
    const first = c.find((n) => typeof n === "string" || typeof n === "number");
    if (first != null) return String(first);
  }
  if (typeof ownerState?.alt === "string" && ownerState.alt) return ownerState.alt;
  return undefined;
}

