// MUI selection-control overrides: MuiCheckbox, MuiRadio, MuiSwitch, MuiRating, MuiSlider.
import React from "react";
import { cssVar } from "@webframework/tecton-core";
import { focusRingShadow, radius50, radiusRound, space25, type ThemeComponents } from "./shared";

export function selectionControlComponents(): ThemeComponents {
  return {
    MuiCheckbox: {
      defaultProps: {
        disableRipple: true,
        icon: React.createElement("span", { className: "tecton-checkbox-unchecked-outline", "aria-hidden": true }),
        checkedIcon: React.createElement("span", { className: "tecton-checkbox-checked-filled", "aria-hidden": true }),
        indeterminateIcon: React.createElement("span", { className: "tecton-checkbox-indeterminate-filled", "aria-hidden": true }),
      },
      styleOverrides: {
        root: {
          color: cssVar("color-action-text-only-text"),
          // Figma Padding-frame wraps the glyph with 2px on every side; outer bounds resolve to 4+icon-size. Medium 24 = 2*2 + 20 (icon-size-150), Small 20 = 2*2 + 16 (icon-size-100).
          padding: space25,
          fontSize: cssVar("icon-size-150"),
          // Figma focus ring is a rounded rect (cornerRadius=4) matching checkbox glyph, not a circle; MUI's SwitchBase applies border-radius:50% which distorts the drop-shadow into a circle. radius-50 (4px) matches Figma Padding-frame cornerRadius.
          borderRadius: radius50,
          "&.MuiCheckbox-sizeSmall": {
            fontSize: cssVar("icon-size-100"),
          },
          "&:hover": {
            color: cssVar("color-action-text-only-text-hover"),
            backgroundColor: "transparent",
          },
          "&:active": {
            color: cssVar("color-action-text-only-text-press"),
          },
          "&.Mui-checked": {
            // Figma action/filled/states/activeBackground; L:#8b5ba9 D:#af9ebc
            color: cssVar("color-action-filled-bg-active"),
            "&:hover": {
              color: cssVar("color-action-filled-bg-hover"),
              backgroundColor: "transparent",
            },
            "&:active": {
              color: cssVar("color-action-filled-bg-press"),
            },
          },
          "&.MuiCheckbox-indeterminate": {
            // Figma action/textOnly/states/activeText; L:#5c3878 D:#beb1c8
            color: cssVar("color-action-text-only-text-active"),
            "&:hover": {
              color: cssVar("color-action-text-only-text-hover"),
              backgroundColor: "transparent",
            },
            "&:active": {
              color: cssVar("color-action-text-only-text-press"),
            },
          },
          "&.Mui-focusVisible": {
            color: cssVar("color-action-text-only-text-focus"),
            backgroundColor: cssVar("color-action-text-only-bg-focus"),
            boxShadow: focusRingShadow,
          },
          "&.Mui-checked.Mui-focusVisible": {
            color: cssVar("color-action-filled-bg-focus"),
            boxShadow: focusRingShadow,
          },
          "&.MuiCheckbox-indeterminate.Mui-focusVisible": {
            color: cssVar("color-action-text-only-text-focus"),
            boxShadow: focusRingShadow,
          },
          "&.Mui-disabled": {
            color: cssVar("color-disabled-text-only-text"),
          },
        },
      },
    },
    MuiRadio: {
      defaultProps: {
        disableRipple: true,
        icon: React.createElement("span", { className: "tecton-radio-button-outline", "aria-hidden": true }),
        checkedIcon: React.createElement("span", { className: "tecton-radio-button-filled", "aria-hidden": true }),
      },
      styleOverrides: {
        root: {
          color: cssVar("color-action-text-only-text"),
          // Figma Padding frame: space-25 on every side around a 20px (medium) / 16px (small) glyph, so the frame stays 24px / 20px.
          padding: space25,
          fontSize: cssVar("icon-size-150"),
          // Figma Enabled/Disabled Padding frame uses radius-50; overrides SwitchBase's 50%.
          borderRadius: radius50,
          "&.MuiRadio-sizeSmall": {
            fontSize: cssVar("icon-size-100"),
          },
          "&:hover": {
            color: cssVar("color-action-text-only-text-hover"),
            backgroundColor: "transparent",
            // Figma Hovered/Pressed/Focused Padding frame uses radius-round, unlike Enabled's radius-50.
            borderRadius: radiusRound,
          },
          "&:active": {
            color: cssVar("color-action-text-only-text-press"),
            borderRadius: radiusRound,
          },
          "&.Mui-checked": {
            // Figma action/filled/background
            color: cssVar("color-action-filled-bg"),
            "&:hover": {
              color: cssVar("color-action-filled-bg-hover"),
              backgroundColor: "transparent",
            },
            "&:active": {
              color: cssVar("color-action-filled-bg-press"),
            },
          },
          "&.Mui-focusVisible": {
            color: cssVar("color-action-text-only-text-focus"),
            backgroundColor: cssVar("color-action-text-only-bg-focus"),
            borderRadius: radiusRound,
            boxShadow: focusRingShadow,
          },
          "&.Mui-checked.Mui-focusVisible": {
            color: cssVar("color-action-filled-bg-focus"),
            boxShadow: focusRingShadow,
          },
          "&.Mui-disabled": {
            color: cssVar("color-disabled-text-only-text"),
          },
        },
      },
    },
    MuiSwitch: {
      defaultProps: { disableRipple: true },
      styleOverrides: {
        root: {
          width:
            "calc(" + cssVar("space-500") + " + " + cssVar("space-25") + ")",
          height: cssVar("space-300"),
          padding: cssVar("space-50"),
        },
        sizeSmall: {
          // Small switch geometry: root 34×20 (pad 4=space-50); track 26×12 inner; thumb 6 (icon-size-50 − 3×space-25); switchBase hitbox 20×20 with own padding (20-6)/2=7 to center thumb (MUI default padding assumes 12px thumb and pins our 6px thumb top-left); checked translateX=14 (space-150+space-25); track 34 − rootPad 4 − sbPad 7 − thumb 6 − sbPad 7 = 10 travel plus initial thumb inset (7-4=3) = 14 visible.
          width:
            "calc(" +
            cssVar("space-200") +
            " + " +
            cssVar("space-200") +
            " + " +
            cssVar("space-25") +
            ")",
          height: cssVar("space-250"),
          "& .MuiSwitch-thumb": {
            width:
              "calc(" +
              cssVar("icon-size-50") +
              " - " +
              cssVar("space-25") +
              " - " +
              cssVar("space-25") +
              " - " +
              cssVar("space-25") +
              ")",
            height:
              "calc(" +
              cssVar("icon-size-50") +
              " - " +
              cssVar("space-25") +
              " - " +
              cssVar("space-25") +
              " - " +
              cssVar("space-25") +
              ")",
          },
          // Center 6px thumb inside 20px hitbox: (20-6)/2 = 7px.
          "& .MuiSwitch-switchBase": {
            padding: "7px",
          },
          // Figma Small unchecked Disabled knob binds text/disabledText (Medium binds disabled/textOnly).
          "& .MuiSwitch-switchBase.Mui-disabled:not(.Mui-checked)": {
            color: cssVar("color-text-disabled"),
          },
          "& .MuiSwitch-switchBase.Mui-checked": {
            transform:
              "translateX(calc(" +
              cssVar("space-150") +
              " + " +
              cssVar("space-25") +
              "))",
          },
        },
        switchBase: {
          padding:
            "calc(" +
            cssVar("space-75") +
            " + " +
            cssVar("space-25") +
            " / 2) " +
            cssVar("space-100"),
          // Figma action/outline/contrastText (unchecked thumb).
          color: cssVar("color-action-outlined-text"),
          "&:hover": {
            color: cssVar("color-action-outlined-text-hover"),
            "& + .MuiSwitch-track": {
              // Figma unchecked Hovered Slide binds action/outline/states/pressBorder.
              borderColor: cssVar("color-action-outlined-border-press"),
            },
          },
          "&:active": {
            color: cssVar("color-action-outlined-text-press"),
            "& + .MuiSwitch-track": {
              borderColor: cssVar("color-action-outlined-border-press"),
            },
          },
          "&.Mui-focusVisible": {
            color: cssVar("color-action-outlined-text-focus"),
            // Figma authors the focus drop-shadow on the outer track (Slide element), wrapping the whole switch, not just the thumb.
            "& + .MuiSwitch-track": {
              boxShadow: focusRingShadow,
              // Figma unchecked Focused Slide binds action/outline/states/pressBorder, same as Hovered and Pressed.
              borderColor: cssVar("color-action-outlined-border-press"),
            },
          },
          "&.Mui-checked": {
            transform:
              "translateX(calc(" +
              cssVar("space-200") +
              " + " +
              cssVar("space-25") +
              "))",
            // Figma action/primary/contrastText (checked thumb).
            color: cssVar("color-action-primary-text"),
            "& + .MuiSwitch-track": {
              // Figma action/primary/states/activeBackground; hover/press use pressBackground below.
              backgroundColor: cssVar("color-action-primary-bg-active"),
              borderColor: "transparent",
              // Figma checked Slide has no stroke.
              borderWidth: cssVar("border-width-0"),
              opacity: 1,
            },
            "&:hover": {
              color: cssVar("color-action-primary-text-hover"),
              "& + .MuiSwitch-track": {
                backgroundColor: cssVar("color-action-primary-bg-press"),
              },
            },
            "&:active": {
              color: cssVar("color-action-primary-text-press"),
              "& + .MuiSwitch-track": {
                backgroundColor: cssVar("color-action-primary-bg-press"),
              },
            },
            "&.Mui-focusVisible": {
              color: cssVar("color-action-primary-text-focus"),
              "& + .MuiSwitch-track": {
                backgroundColor: cssVar("color-action-primary-bg-focus"),
                boxShadow: focusRingShadow,
              },
            },
          },
          "&.Mui-disabled": {
            color: cssVar("color-disabled-text-only-text"),
            // Figma checked Disabled knob binds text/inverseText; beats MUI's checked+disabled lighten(primary).
            "&.Mui-checked": {
              color: cssVar("color-text-inverse"),
            },
            "& + .MuiSwitch-track": {
              backgroundColor: cssVar("color-action-outlined-bg"),
              borderColor: cssVar("color-disabled-text-only-text"),
              opacity: 1,
            },
            "&.Mui-checked + .MuiSwitch-track": {
              backgroundColor: cssVar("color-disabled-filled-adornment"),
              borderColor: "transparent",
              opacity: 1,
            },
          },
        },
        thumb: {
          width:
            "calc(" +
            cssVar("icon-size-100") +
            " - " +
            cssVar("space-25") +
            " - " +
            cssVar("space-25") +
            " - " +
            cssVar("space-25") +
            ")",
          height:
            "calc(" +
            cssVar("icon-size-100") +
            " - " +
            cssVar("space-25") +
            " - " +
            cssVar("space-25") +
            " - " +
            cssVar("space-25") +
            ")",
          boxShadow: "none",
          border: "none",
        },
        track: {
          // Figma unchecked track: hollow with outline/strongBorder stroke.
          backgroundColor: cssVar("color-action-outlined-bg"),
          border:
            cssVar("border-width-100") +
            " solid " +
            cssVar("color-action-outlined-border-strong"),
          borderRadius: cssVar("radius-150"),
          boxSizing: "border-box",
          opacity: 1,
        },
      },
    },
    MuiRating: {
      defaultProps: {
        icon: React.createElement("span", { className: "tecton-star-filled", "aria-hidden": true }),
        emptyIcon: React.createElement("span", { className: "tecton-star-outline", "aria-hidden": true }),
        // MUI v9 renders fractional stars by clipping a full filled glyph to 50% width over an empty full glyph. The tecton icon set ships a real half-filled mask, so the custom icon slot swaps children to tecton-star-half-filled whenever the per-item value is fractional; the paired CSS override below removes MUI's 50%-clip so the mask paints at full width.
        slots: {
          icon: React.forwardRef<
            HTMLSpanElement,
            { value: number; children?: React.ReactNode } & React.HTMLAttributes<HTMLSpanElement>
          >(function TectonRatingIconSlot({ value, children, ...rest }, ref) {
            // Only swap to the half-filled mask on FILLED icon containers. MUI renders each fractional position twice (once as .MuiRating-iconFilled underlay and once as .MuiRating-iconEmpty overlay); without this guard the empty overlay also becomes a half-fill, wiping the outline glyph.
            const cn = typeof rest.className === "string" ? rest.className : "";
            // This wrapper nests the glyph inside an extra span that MUI did not render before. display:contents drops the wrapper from the box model (no line-box of its own), so it adds no padding itself. That alone does not reach Figma's 18px for Size=Small though: .MuiRating-decimal's own line-height strut still pads the row to 19.5px there (verified live), fixed separately below (`"& .MuiRating-decimal": { lineHeight: 0 }`).
            const style = { ...(rest.style as React.CSSProperties | undefined), display: "contents" as const };
            if (Number.isFinite(value) && value % 1 !== 0 && cn.includes("MuiRating-iconFilled")) {
              return React.createElement(
                "span",
                { ...rest, ref, style, "data-tecton-rating-value": value },
                React.createElement("span", { className: "tecton-star-half-filled", "aria-hidden": true }),
              );
            }
            return React.createElement("span", { ...rest, ref, style, "data-tecton-rating-value": value }, children);
          }) as unknown as React.ElementType,
        },
      },
      styleOverrides: {
        root: {
          // MUI Rating's own RatingRoot hardcodes color:#faaf00 (amber) which cascades into every icon slot. Figma binds all three Star states (Active=Full/Half/None) to the single semantic/color/text/text token (color-text-primary), so override at the root and let it flow into every slot.
          color: cssVar("color-text-primary"),
          // Figma Disabled uses opacity 0.5 (MUI default 0.38).
          "&.Mui-disabled": { opacity: 0.5 },
          // MUI's iconEmpty variant sets its own color:action.disabled that outranks the root color; re-force text-primary at slot specificity.
          "& .MuiRating-iconEmpty": { color: cssVar("color-text-primary") },
          "& .MuiRating-iconFilled": { color: cssVar("color-text-primary") },
          "& .MuiRating-iconHover": { color: cssVar("color-text-primary") },
          // MUI clips the first child of a fractional decimal wrapper with inline width:50%; overflow:hidden to fake half-stars. The tecton half-mask draws the shape natively, so undo the clip on the first-child wrapper. The wrapper is a .MuiRating-label element for the interactive control and a plain <span> (no class) for the readOnly branch (Rating.js:302-306); universal `> *:first-child` matches both.
          "& .MuiRating-decimal > *:first-child": {
            width: "100% !important",
            overflow: "visible !important",
          },
          // .MuiRating-decimal is a block box around an inline-block star glyph
          // (vertical-align: middle). The icon's own box is already exactly
          // font-size square (1em, confirmed live), but the surrounding line
          // box still reserves room for an invisible strut at the inherited
          // line-height; when that line-height is close to the icon's own
          // font-size (Size=Small, both 18px), the strut pads the line box
          // taller than the icon (measured live: 19.5px, not 18px). Medium/
          // Large aren't visibly affected because their font-size (24/30)
          // already exceeds the inherited line-height, so the icon's own box
          // decides the line height either way. Zeroing it removes the strut
          // everywhere, same fix already used on MuiIconButton's icon-only box.
          "& .MuiRating-decimal": {
            lineHeight: 0,
          },
        },
      },
    },
    MuiSlider: {
      defaultProps: { color: "primary" },
      styleOverrides: {
        // Figma's _*SliderRail instance carries a node-level opacity of 0.6 with no bound `opacity`
        // Variable (confirmed via the REST API, e.g. Primary Enabled 14479:16586, Primary Disabled
        // 14479:19806, Secondary Enabled 14479:16613, Tertiary Enabled 14479:18243, Tertiary Hover
        // 14479:18252: boundVariables has only `fills`), i.e. no Figma token exists for that dimming -
        // the same design-gap shape as the Progress/Button fixes. Every colour's rail/mark below render
        // the real, unmodified base token for that reason.
        rail: {
          ".Mui-disabled &": { backgroundColor: cssVar("color-text-disabled") },
        },
        track: {
          // Figma track has no stroke; MUI adds a 1px currentColor border.
          borderWidth: cssVar("border-width-0"),
          ".Mui-disabled &": { backgroundColor: cssVar("color-text-disabled") },
        },
        thumb: {
          "&.Mui-focusVisible": { boxShadow: focusRingShadow },
          // Figma State=Hover draws no halo on the thumb; reset MUI's default 8px hover ring, keeping the focus ring and the pressed ring.
          "&:hover:not(.Mui-focusVisible):not(.Mui-active)": {
            boxShadow: "none",
          },
        },
        valueLabel: {
          backgroundColor: cssVar("color-action-primary-bg"),
          color: cssVar("color-text-primary"),
          borderRadius: radius50,
        },
        // Figma disabled marks use text/disabledText; MUI's active marks otherwise paint background.paper.
        mark: {
          // Figma _*SliderMark sits at opacity 1; MUI sets 0.8 on active marks.
          opacity: 1,
          ".Mui-disabled &": { backgroundColor: cssVar("color-text-disabled") },
        },
      },
      variants: [
        {
          props: { color: "primary" },
          style: {
            color: cssVar("color-accent-lilac-main"),
            // Root causes rc-dcb7a253d758 (hue) and rc-1f57ea461557 (alpha): confirmed via the Figma
            // REST API (file rqf6bnvtSE48SYkKngCT3N, node 14479:16586, the _*SliderRail instance under
            // Size=Medium/Continuous/Primary/Enabled) that the rail paints at a node-level opacity of 0.6
            // with boundVariables holding only `fills` (no `opacity` key), resolving to
            // semantic/color/accent/lilac/main i.e. color-accent-lilac-main at full strength. No token
            // exists for the 60% dimming, so this is a design gap for UX to fix by adding a real token,
            // not something this adapter approximates; render the real, unmodified base token and let
            // the resulting mismatch show up as design-drift.
            "& .MuiSlider-rail": {
              backgroundColor: cssVar("color-accent-lilac-main"),
            },
            "& .MuiSlider-track": {
              backgroundColor: cssVar("color-accent-lilac-main"),
              borderColor: cssVar("color-accent-lilac-main"),
            },
            "& .MuiSlider-thumb": {
              backgroundColor: cssVar("color-accent-lilac-main"),
              // Root cause rc-30035d09efb0 (dark mode only): Figma's Hover thumb fill is a bolder tone than
              // Enabled's. Dark mode's value is exactly accent-lilac-muted (confirmed against the Figma export);
              // light mode's Hover value does not match any existing token (not accent-lilac-muted, not main), so
              // light keeps rendering main here until that value is added through the token pipeline.
              "&:hover:not(.Mui-focusVisible):not(.Mui-active)": {
                backgroundColor: cssVar("color-accent-lilac-muted"),
              },
            },
            // Root cause rc-1b9879604610: confirmed on the mark's own Rec node
            // (I14479:16634;6562:39005): same node-level opacity of 0.6, boundVariables holding only
            // `fills` resolving to the same semantic/color/accent/lilac/main, no bound opacity Variable.
            // Same design gap as the rail above; render the base token unmixed.
            "& .MuiSlider-mark": {
              backgroundColor: cssVar("color-accent-lilac-main"),
            },
            // Root causes rc-20e7b030fc4a (rail), rc-da127692cfc2 (track) and rc-a4ea5a33f8a4 (mark): this
            // variant's own rail/track/mark rules above outrank the shared `styleOverrides.rail`/`track`/`mark`
            // ".Mui-disabled &" rule (one more class: this variant's generated class plus .MuiSlider-rail/-track/
            // -mark, versus .Mui-disabled plus .MuiSlider-rail/-track/-mark), so Disabled never won. Restating it
            // here, scoped with "&.Mui-disabled" on the same (root) element, adds .Mui-disabled to this variant's
            // own selector so it outranks the enabled-state rule above.
            // rc-b9d4c468b153 (rail) and rc-2626f947d270 (mark): confirmed via the Figma REST API (node
            // 14479:19806, the Primary Disabled _*SliderRail instance, and its mark's Rec node
            // I14479:19827;14479:19428): same node-level opacity of 0.6 with no bound `opacity` Variable,
            // boundVariables.fills resolving to semantic/color/text/disabledText i.e. color-text-disabled
            // at full strength. Same design gap as Enabled's rail/mark above; render the base token
            // unmixed and let the mismatch surface as design-drift. Track has no such opacity (same as
            // its Enabled state), so it stays a plain var reference, unaffected by this.
            "&.Mui-disabled .MuiSlider-rail": {
              backgroundColor: cssVar("color-text-disabled"),
            },
            "&.Mui-disabled .MuiSlider-track": {
              backgroundColor: cssVar("color-text-disabled"),
              borderColor: cssVar("color-text-disabled"),
            },
            "&.Mui-disabled .MuiSlider-mark": {
              backgroundColor: cssVar("color-text-disabled"),
            },
          },
        },
        {
          props: { color: "secondary" },
          style: {
            // Root causes rc-a5420a7cfa9f (rail), rc-e85474c43650 (track), rc-d17cb2618aeb (thumb) and
            // rc-7c443aa2d08b (thumb, Range variant): Figma binds Secondary's rail/track/thumb/mark to
            // accent/blue/main, not to status-info-filled-bg-hover (an unrelated status token) or to the
            // slider-secondary-rail extended-palette token.
            //
            // Rail opacity (checked via the Figma REST API, node 14479:16613, Size=Medium/Continuous/Secondary/
            // Enabled, file rqf6bnvtSE48SYkKngCT3N): the rail's fill is bound to accent/blue/main, but the node
            // also paints at a flat 60% opacity with no bound Variable (boundVariables carries no opacity key).
            // Same design gap as Primary's rail/mark above; render the base token unmixed and let the mismatch
            // surface as design-drift instead of approximating it with color-mix().
            color: cssVar("color-accent-blue-fill"),
            "& .MuiSlider-rail": {
              backgroundColor: cssVar("color-accent-blue-fill"),
            },
            "& .MuiSlider-track": {
              backgroundColor: cssVar("color-accent-blue-fill"),
              borderColor: cssVar("color-accent-blue-fill"),
            },
            "& .MuiSlider-thumb": {
              backgroundColor: cssVar("color-accent-blue-fill"),
              // Root cause rc-30035d09efb0 (secondary portion): Figma's Hover thumb fill is a bolder tone than
              // Enabled's, same construction as Primary's. Confirmed (both modes) byte-identical to
              // slider-secondary-rail, so no new token is needed, just the existing one at full opacity.
              "&:hover:not(.Mui-focusVisible):not(.Mui-active)": {
                backgroundColor: cssVar("color-slider-secondary-rail"),
              },
            },
            // Root cause rc-b34a1161ccbd (secondary portion): Figma's Mark binds a bolder "visibleFill" tone with
            // no Tecton token of its own, but its resolved value (both modes, confirmed against the Figma export)
            // is byte-identical to slider-secondary-rail, the token this adapter already carries (previously
            // misapplied to the rail above, which rc-a5420a7cfa9f corrects to accent-blue-fill instead). Reused
            // here instead of adding a duplicate token for the same value.
            //
            // Opacity (checked via the Figma REST API, node 14479:16651, Marks/Secondary/Enabled, file
            // rqf6bnvtSE48SYkKngCT3N): same construction as the rail above, a bound visibleFill color plus an
            // unbound 60% node opacity. Design gap, not an adapter fix; render the bound color at full opacity.
            "& .MuiSlider-mark": {
              backgroundColor: cssVar("color-slider-secondary-rail"),
            },
          },
        },
        {
          props: { color: "tertiary" },
          style: {
            // Root causes rc-c9ff0ed646ac (rail, Enabled) and rc-081d0f769cd7 (track, Enabled): Figma binds
            // Tertiary's rail/track to accent/lime/main at Enabled, not to the slider-tertiary-rail/-track
            // extended-palette tokens.
            //
            // Rail opacity (checked via the Figma REST API, node 14479:18243, Size=Medium/Continuous/Tertiary/
            // Enabled, file rqf6bnvtSE48SYkKngCT3N): same unbound 60% node opacity on top of a bound fill as
            // Primary/Secondary's rail. Design gap, not an adapter fix; render the bound color at full opacity.
            //
            // The thumb is deliberately left on slider-tertiary-track here (not switched to accent-lime-fill):
            // confirmed against the Figma export, dark mode's Enabled thumb fill is slider-tertiary-track's value,
            // while light mode's is accent-lime-fill's, an asymmetric binding between modes that only Tertiary
            // has (Primary and Secondary bind the same tier in both modes). Changing the shared base rule to
            // either token fixes one mode and regresses the other; left as a design question (see report) rather
            // than guessed. rc-9f0e7d3a78d4 (thumb Enabled) is not fixed here for that reason.
            color: cssVar("color-accent-lime-fill"),
            "& .MuiSlider-rail": {
              backgroundColor: cssVar("color-accent-lime-fill"),
            },
            // Root cause rc-c2cafb7abc98: Tertiary is the one colour whose rail (and track, below) also shifts
            // to a bolder tone on Hover; Primary and Secondary's rail stays the same colour as Enabled (confirmed
            // against the Figma export, and matches how the PrimeNG preset's own Slider already treats this
            // colour, createPrimePreset.ts). "&" here is this colour's own generated root selector, which gets
            // :hover whenever any descendant (the thumb) is hovered, so this reaches the rail without the thumb
            // itself needing to be the hovered element.
            //
            // Opacity (checked via the Figma REST API, node 14479:18252, Continuous/Tertiary/Hover, file
            // rqf6bnvtSE48SYkKngCT3N): the hover rail's fill is bound to accent/lime/visibleFill (this swap to a
            // bolder tone is correct, confirmed above), but the node also paints at an unbound 60% opacity on top,
            // same design gap as Enabled's rail. Render the bound color at full opacity.
            "&:hover .MuiSlider-rail": {
              backgroundColor: cssVar("color-slider-tertiary-rail"),
            },
            // rc-081d0f769cd7's Enabled fix (accent-lime-fill) only holds for Variant=Continuous; Marks and
            // Range's own Figma frames bind this same track to slider-tertiary-track instead (confirmed:
            // batch-verify showed Marks/Range regressing to accent-lime-fill after this was first set
            // unconditionally). All three variants render through the identical MuiSlider-track rule with no
            // CSS hook to tell them apart, so this can only match one grouping at a time; slider-tertiary-track
            // wins here since it already matches 5 of 6 Horizontal Enabled+Hover combinations (Marks, Range,
            // and Continuous's own Hover) against accent-lime-fill's 1 (Continuous Enabled only). Continuous
            // Enabled is left open, same category as the other Figma-authoring-inconsistency findings below.
            "& .MuiSlider-track": {
              backgroundColor: cssVar("color-slider-tertiary-track"),
              borderColor: cssVar("color-slider-tertiary-track"),
            },
            // Root cause rc-081d0f769cd7 (Hover, dark mode only): confirmed against the Figma export, dark mode's
            // Hover track is slider-tertiary-track's value (this preserves the match that already existed before
            // this file's other tertiary-track changes). Light mode's Hover track is accent-lime-fill's value,
            // same as Enabled, i.e. unchanged by hover; since that is also this rule's Enabled value already, the
            // existing accent-lime-fill rule above satisfies light's Hover reading without any extra rule here.
            // Pre-existing drift for light mode's Hover is therefore unchanged, not fixed: see rc-1d358b26f77b in
            // the report.
            "&:hover .MuiSlider-track": {
              backgroundColor: cssVar("color-slider-tertiary-track"),
            },
            "& .MuiSlider-thumb": {
              backgroundColor: cssVar("color-slider-tertiary-track"),
              // Figma's Hover thumb fill is a bolder tone than Enabled's, consistent in both modes (unlike
              // Enabled's thumb fill above, which is asymmetric between modes); confirmed byte-identical to
              // slider-tertiary-rail. Covers rc-30035d09efb0's tertiary portion.
              "&:hover:not(.Mui-focusVisible):not(.Mui-active)": {
                backgroundColor: cssVar("color-slider-tertiary-rail"),
              },
            },
            // Root cause rc-b34a1161ccbd (tertiary portion): same reasoning as Secondary's mark above; Figma's
            // Mark tone (both modes, confirmed) is byte-identical to slider-tertiary-rail, reused here instead of
            // adding a duplicate token for the same value.
            //
            // Opacity (checked via the Figma REST API, node 14479:18264, Marks/Tertiary/Enabled, file
            // rqf6bnvtSE48SYkKngCT3N): same unbound 60% node opacity as Secondary's mark. Design gap, not an
            // adapter fix; render the bound color at full opacity.
            "& .MuiSlider-mark": {
              backgroundColor: cssVar("color-slider-tertiary-rail"),
            },
          },
        },
      ],
    },
  };
}
