// Shared by MuiToggleButtonGroup's middleButton and lastButton style overrides below: both need the identical vertical-orientation divider, so one function covers both slots instead of two copies that could silently drift apart.
function verticalDividerStyle({ ownerState }: { ownerState: { orientation?: "horizontal" | "vertical" } }) {
  return ownerState.orientation === "vertical"
    ? {
        "&:not(.Mui-disabled)": {
          marginTop: 0,
          borderTop: `${borderW100} solid ${cssVar("color-divider-subtle")}`,
          "& > :first-child": { marginTop: `calc(-1 * ${borderW100})` },
        },
      }
    : {};
}

