// Helpers and token shorthands shared by createMuiTheme.ts and the per-category component override files.
import React from "react";
import type { ThemeOptions } from "@mui/material/styles";
import { cssVar, textStyles } from "@webframework/tecton-core";

// The ThemeOptions.components shape; each category file returns a slice of it and components/index.ts merges them.
export type ThemeComponents = NonNullable<ThemeOptions["components"]>;

// Factory returns a stable React function-component that renders a tecton-icon span with the given CSS classes. Used for MUI/MUI-X slots which expect a ComponentType (not a ReactElement). Cached by className so slot references stay reference-stable across renders (avoids remount churn in DataGrid/DatePicker slot APIs).
const slotIconCache = new Map<string, React.FC<Record<string, unknown>>>();
export function slotIcon(className: string): React.FC<Record<string, unknown>> {
  let comp = slotIconCache.get(className);
  if (!comp) {
    comp = (props) => {
      const passed = (props?.className as string | undefined) ?? "";
      const merged = passed ? `${className} ${passed}` : className;
      return React.createElement("span", { ...props, className: merged, "aria-hidden": true });
    };
    comp.displayName = "TectonSlotIcon";
    slotIconCache.set(className, comp);
  }
  return comp;
}

// Sans-serif fallback so text never renders in serif if font files fail to load.
export const FONT_FAMILY_SANS = `${cssVar("font-family-sans")}, sans-serif`;
// Monospace fallback for tabular data cells (Figma Data/Medium on Table body); IBM Plex Mono self-hosted alongside Figtree; system-ui monospace keeps numbers tabular on font-load failure.
export const FONT_FAMILY_MONO = `${cssVar("font-family-mono")}, ui-monospace, "SFMono-Regular", Menlo, Monaco, "Cascadia Mono", "Roboto Mono", Consolas, monospace`;

// A token with no `weight` field (e.g. mediumParagraph) has no matching --tecton-font-weight-*
// variable. Omitting fontWeight entirely lets it inherit rather than inventing a value: a design
// gap for Figma/UX to close with a real token, not something this adapter should fill in.
export function variantFromTextStyle(styleName: keyof typeof textStyles, fontFamily: string = FONT_FAMILY_SANS) {
  const key = cssKey(styleName);
  const hasOwnWeight = (textStyles[styleName] as { weight?: number }).weight !== undefined;
  return {
    fontFamily,
    fontSize: cssVar(`font-size-${key}`),
    ...(hasOwnWeight ? { fontWeight: cssVar(`font-weight-${key}`) } : {}),
    lineHeight: cssVar(`line-height-${key}`),
  };
}

// Normalises textStyles keys for CSS variable lookup: display1 -> display-1, heading1 -> heading-1, smallData -> small-data, large -> large, etc.
function cssKey(key: keyof typeof textStyles): string {
  return key
    .replace(/([a-z])([A-Z])/g, "$1-$2")
    .replace(/([a-z])(\d)/g, "$1-$2")
    .toLowerCase();
}

// Tecton focus-ring: 2px pink ring (--tecton-color-focus-ring) offset by 1px of the surrounding surface, matching Figma's double-shadow effect.
export const focusRingShadow = [
  `0 0 0 1px ${cssVar("color-bg-default")}`,
  `0 0 0 3px ${cssVar("color-focus-ring")}`,
].join(", ");

// Token shorthands shared by the component override files.
export const radius50 = cssVar("radius-50");
export const radiusRound = cssVar("radius-round");
export const space25 = cssVar("space-25");
export const space50 = cssVar("space-50");
export const space75 = cssVar("space-75");
export const space100 = cssVar("space-100");
export const space150 = cssVar("space-150");
export const space200 = cssVar("space-200");
export const borderW100 = cssVar("border-width-100");
