// Merges the per-category override files into the single ThemeOptions.components object createMuiTheme() consumes. Each category owns a disjoint set of component keys, so spread order carries no precedence.
import type { ThemeMode } from "@webframework/tecton-core";
import { baselineComponents } from "./baseline";
import { buttonComponents } from "./buttons";
import { inputComponents } from "./inputs";
import { selectionControlComponents } from "./selectionControls";
import { dataDisplayComponents } from "./dataDisplay";
import { surfaceComponents } from "./surfaces";
import { overlayComponents } from "./overlays";
import { navigationComponents } from "./navigation";
import { feedbackComponents } from "./feedback";
import { pickerComponents } from "./pickers";
import { tableComponents } from "./tables";
import type { ThemeComponents } from "./shared";

export function buildComponents(mode: ThemeMode): ThemeComponents {
  return {
    ...baselineComponents(),
    ...buttonComponents(),
    ...inputComponents(),
    ...selectionControlComponents(),
    ...dataDisplayComponents(mode),
    ...surfaceComponents(),
    ...overlayComponents(),
    ...navigationComponents(),
    ...feedbackComponents(),
    ...pickerComponents(),
    ...tableComponents(),
  };
}
