import { useCallback, useState } from "react";

// Tracks keyboard vs pointer input, since MUI's own focus-visible detection fails for Select/TextField.
// Shared via globalThis so two Tecton bundles on one page don't double up on document listeners.
const MODALITY_KEY = "__WEBFRAMEWORK_TECTON_FOCUS_MODALITY__";

type ModalityState = { lastInputWasKeyboard: boolean };

// Returns the page-wide modality tracker, creating it and attaching the document listeners on first call.
function sharedModalityState(): ModalityState {
  const scope = globalThis as unknown as Record<string, ModalityState | undefined>;
  const existing = scope[MODALITY_KEY];
  if (existing) return existing;
  const state: ModalityState = { lastInputWasKeyboard: false };
  scope[MODALITY_KEY] = state;
  if (typeof document !== "undefined") {
    document.addEventListener(
      "keydown",
      () => {
        state.lastInputWasKeyboard = true;
      },
      true
    );
    document.addEventListener(
      "pointerdown",
      () => {
        state.lastInputWasKeyboard = false;
      },
      true
    );
  }
  return state;
}

export type KeyboardFocusVisible = {
  /** True only when the element is currently focused AND that focus was most recently triggered by the keyboard (Tab), not a mouse/touch click. */
  focusVisible: boolean;
  onFocus: () => void;
  onBlur: () => void;
};

// Reports whether the element's current focus was triggered by the keyboard rather than a mouse or touch click.
export function useKeyboardFocusVisible(): KeyboardFocusVisible {
  // Must run on every call, not just inside onFocus, so the listeners are attached before the first Tab press.
  const modality = sharedModalityState();
  const [focusVisible, setFocusVisible] = useState(false);

  const onFocus = useCallback(() => {
    setFocusVisible(modality.lastInputWasKeyboard);
  }, [modality]);

  const onBlur = useCallback(() => {
    setFocusVisible(false);
  }, []);

  return { focusVisible, onFocus, onBlur };
}
