// MUI surface overrides: MuiPaper, MuiCard, MuiCardHeader, MuiCardActionArea, MuiAccordion, MuiAccordionSummary, MuiAccordionDetails.
import React from "react";
import { cssVar } from "@webframework/tecton-core";
import {
  borderW100,
  focusRingShadow,
  radius50,
  space50,
  space75,
  space100,
  type ThemeComponents,
} from "./shared";

export function surfaceComponents(): ThemeComponents {
  return {
    MuiPaper: {
      styleOverrides: {
        // Figma Paper elevations → MUI: E0 (surface/base/bg-default) variant="outlined"; E1 (surface/elevation-1/bg-paper) default root; E2 (surface/elevation-2/component-top-nav-solid-background) elevation={2}+ (consumer-wired). Border = surface/*/border = divider-subtle; radius = borderRadius/50.
        root: {
          backgroundImage: "none",
          backgroundColor: cssVar("color-bg-paper"),
          color: cssVar("color-text-primary"),
          borderRadius: cssVar("radius-50"),
          // Figma has NO drop shadow on any Paper elevation; surfaces are differentiated by bg color; suppress MUI defaults so every <Paper> reads flat regardless of elevation.
          boxShadow: "none",
          // Elevation 0: MUI's outlined default uses palette.divider (medium); Figma surface/*/border = divider-subtle.
          "&.MuiPaper-outlined": {
            backgroundColor: cssVar("color-bg-default"),
            borderColor: cssVar("color-divider-subtle"),
          },
        },
      },
    },
    MuiCard: {
      // Tecton renames MUI's built-in "elevation" surface to "elevated" so the value reads parallel to "outlined". Same rendered surface: bg-paper + 1px divider-subtle + radius-100. "elevation" stays as a silent alias so no consumer breaks.
      defaultProps: { variant: "elevated" },
      styleOverrides: {
        root: {
          // Figma Card: Elevation 1 (default) = surface/elevation-1/background (bg-paper); border = surface/*/border (divider-subtle); radius = 8px (borderRadius/100). Outlined = E0 = surface/base/background (bg-default).
          backgroundColor: cssVar("color-bg-paper"),
          border: `${borderW100} solid ${cssVar("color-divider-subtle")}`,
          borderRadius: cssVar("radius-100"),
          "&.MuiPaper-outlined": {
            backgroundColor: cssVar("color-bg-default"),
          },
          // Same shared focus ring every other focusable component uses. Plain
          // Card has no tabIndex (never reached by live keyboard focus), but
          // the Figma State=Focused variant still needs real CSS behind it -
          // confirmed live: nothing was defined here, so the stories' Focused
          // demo cells (which apply the real Mui-focusVisible class, not a
          // faked ring) rendered pixel-identical to Enabled.
          "&.Mui-focusVisible": { boxShadow: focusRingShadow },
        },
      },
      variants: [
        {
          props: { variant: "elevated" },
          style: {
            backgroundColor: cssVar("color-bg-paper"),
            border: `${borderW100} solid ${cssVar("color-divider-subtle")}`,
            borderRadius: cssVar("radius-100"),
          },
        },
        {
          props: { variant: "elevation" },
          style: {
            backgroundColor: cssVar("color-bg-paper"),
            border: `${borderW100} solid ${cssVar("color-divider-subtle")}`,
            borderRadius: cssVar("radius-100"),
          },
        },
      ],
    },
    MuiCardHeader: {
      styleOverrides: {
        // Figma Card {Subheader} = Typography/semantic/text/small; MUI renders it via body1 (without an
        // avatar) or body2 (with one), neither of which is `small`, so all three properties are pinned.
        subheader: {
          fontSize: cssVar("font-size-small"),
          fontWeight: cssVar("font-weight-small"),
          lineHeight: cssVar("line-height-small"),
        },
      },
    },
    MuiCardActionArea: {
      defaultProps: { disableRipple: true },
      styleOverrides: {
        root: {
          // Figma surface/base/activeBackground (L:#e7e3eb D:#2c2730) + surface/elevation-1/activeBorder (L:#9d6ab5 D:#7d7284).
          "&:hover": {
            backgroundColor: cssVar("color-surface-base-bg-active"),
          },
          "&.Mui-focusVisible": {
            backgroundColor: cssVar("color-surface-base-bg-active"),
          },
          "&:active": {
            backgroundColor: cssVar("color-surface-base-bg-active"),
            outline: `${borderW100} solid ${cssVar(
              "color-surface-elevation-1-border-active"
            )}`,
            outlineOffset: "-2px",
          },
        },
      },
    },
    MuiAccordion: {
      // disableGutters:true; MUI v9's default 16px top-margin on non-:first-of-type accordions vanishes on expand, jittering siblings by 16px on open/close; disabling gutters zeroes both rules so open/close is stable.
      defaultProps: { disableGutters: true },
      styleOverrides: {
        root: {
          // Figma Accordion root = action/tertiary/background = transparent, no elevation/shadow. Dividers are NOT part of Accordion; they appear only when placed inside an AccordionGroup.
          backgroundColor: cssVar("color-action-tertiary-bg"),
          boxShadow: "none",
          "&:before": { display: "none" },
          // Zero MUI's margin at every specificity level (its `:not(:first-of-type)` rule out-ranks our root); !important is the only reliable defuse.
          margin: "0 !important",
          "&.Mui-expanded": { margin: "0 !important" },
          "&:not(:first-of-type)": { marginTop: "0 !important" },
          // MUI's baseline paints a translucent disabledBackground overlay; Figma Disabled stays transparent.
          "&.Mui-disabled": {
            backgroundColor: cssVar("color-action-tertiary-bg"),
          },
        },
      },
      variants: [
        // Figma Accordion State=Activated (distinct from Expanded): whole row (summary + details + expand icon) picks up the tertiary-active tokens so it reads as one continuous tinted surface.
        {
          props: { activated: true },
          style: {
            backgroundColor: cssVar("color-action-tertiary-bg-active"),
            // Figma Activated Container binds tertiary pressBackground (the outer frame keeps activeBackground); dark resolves both to the same value.
            "& .MuiAccordionSummary-root": {
              backgroundColor: cssVar("color-action-tertiary-bg-press"),
              color: cssVar("color-action-tertiary-text"),
            },
            "& .MuiAccordionDetails-root": {
              backgroundColor: cssVar("color-action-tertiary-bg-active"),
              color: cssVar("color-action-tertiary-text"),
            },
            // Figma Activated Expand Icon vector reads tertiary contrastText (text), not the adornment role.
            "& .MuiAccordionSummary-expandIconWrapper": {
              color: cssVar("color-action-tertiary-text"),
            },
            // Figma Activated Expanded=True Container has square bottom corners, so the tinted summary joins the tinted details.
            "& .MuiAccordionSummary-root.Mui-expanded": {
              borderBottomLeftRadius: cssVar("radius-0"),
              borderBottomRightRadius: cssVar("radius-0"),
            },
          },
        },
      ],
    },
    MuiAccordionSummary: {
      defaultProps: {
        expandIcon: React.createElement("span", { className: "tecton-chevron-down-outline", "aria-hidden": true }),
      },
      styleOverrides: {
        root: {
          // Figma Container radius sits on the summary row (where hover/focus/press/active paint), not on the outer Accordion (no visible bg/border of its own).
          borderRadius: radius50,
          // Figma Container pt/pb=6 pl/pr=8 h=32 vs MUI default 12/16/48.
          paddingBlock: space75,
          paddingInline: space100,
          // Figma Container item spacing (space-100) between the label and the expand icon.
          columnGap: space100,
          minHeight: cssVar("space-400"),
          "&.Mui-expanded": { minHeight: cssVar("space-400") },
          color: cssVar("color-action-tertiary-text"),
          "&:hover": {
            backgroundColor: cssVar("color-action-tertiary-bg-hover"),
            color: cssVar("color-action-tertiary-text-hover"),
          },
          "&:active": {
            backgroundColor: cssVar("color-action-tertiary-bg-press"),
            color: cssVar("color-action-tertiary-text-press"),
          },
          "&.Mui-focusVisible": {
            backgroundColor: cssVar("color-action-tertiary-bg-focus"),
            color: cssVar("color-action-tertiary-text-focus"),
            boxShadow: focusRingShadow,
          },
          // Mui-expanded intentionally has NO bg/text tinting; Figma "Enabled Expanded=True" is transparent; the tinted look belongs to the separate "Activated" state (Accordion `activated` prop).
          "&.Mui-disabled": {
            color: cssVar("color-disabled-text-only-text"),
            opacity: 1,
          },
        },
        content: {
          // MUI bakes a top margin on .MuiAccordionSummary-content that inflates minHeight to 48; zero it (including Mui-expanded) so paddingBlock drives height alone.
          margin: 0,
          "&.Mui-expanded": { margin: 0 },
          // Figma Primary Label: min-height space-250 (20), label centered in it.
          minHeight: cssVar("space-250"),
          alignItems: "center",
        },
        expandIconWrapper: {
          // Figma Accordion Expand Icon: padding-left space-50 before the icon.
          paddingLeft: space50,
          // Rotate about the icon center (not the box center) so the left padding does not shift the chevron on expand.
          transformOrigin: "calc(100% - 0.5em) center",
          // Figma icon slot is 20x20 (24 wide with the padding); the default chevron span is 1em, so the wrapper font-size sizes it.
          fontSize: cssVar("icon-size-150"),
          // Figma Expand Icon vector reads the tertiary contrastText (text) role, not the adornment role.
          color: cssVar("color-action-tertiary-text"),
          ".MuiAccordionSummary-root:hover &": {
            color: cssVar("color-action-tertiary-text-hover"),
          },
          ".MuiAccordionSummary-root:active &": {
            color: cssVar("color-action-tertiary-text-press"),
          },
          ".MuiAccordionSummary-root.Mui-focusVisible &": {
            color: cssVar("color-action-tertiary-text-focus"),
          },
          ".Mui-disabled &": {
            color: cssVar("color-disabled-text-only-text"),
          },
        },
      },
    },
    MuiAccordionDetails: {
      // Figma AccordionDetails: space-100 all sides (MUI default `8px 16px 16px` is asymmetric).
      styleOverrides: {
        root: {
          padding: space100,
        },
      },
    },
  };
}
